template:
trait Transform {
    type Output;
    fn transform(&self) -> Self::Output;
}
struct Meters(i32);
struct Feet(i32);

impl Transform for Meters {
    ⟦assoc_type_slot⟧
    fn transform(&self) -> ⟦return_type_slot⟧ { Feet(self.0 * 3) }
}

fn main() {
    let m = Meters(5);
    println!("{}", m.transform().0);
}

tests:
#[test]
fn transforms_meters() {
    let m = Meters(10);
    assert_eq!(m.transform().0, 30);
}
